CREATE TABLE "PBM_BUSINESS_RULES"."PROVIDER_NETWORK"
(
	"NETWORK_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL,
	"NETWORK_NAME" VARCHAR2(250) NOT NULL,
	"PAYER_ID" NUMBER NOT NULL,
    "IS_DELETED" CHAR(1) DEFAULT '0',
    "CREATED_BY" VARCHAR2 (30) NOT NULL,
    "DELETED_BY" VARCHAR2(30) NOT NULL,
    "LAST_UPDATE_DATE" DATE NOT NULL,
	CONSTRAINT PK_NetworkID PRIMARY KEY ("NETWORK_ID"),
	CONSTRAINT UK_Network_Payer UNIQUE ("NETWORK_NAME","PAYER_ID")
);